#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 16
#define NUM_THREADS 128
#define WARP_M 32
#define WARP_N 32
#define TM 8
#define TN 4
#define STAGES 3
#define SMEM_A_STRIDE 32
__device__ __forceinline__ void cp_async16(void* smem_dst, const void* gmem_src) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    const unsigned s = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(s), "l"(gmem_src));
#else
    *reinterpret_cast<float4*>(smem_dst) = *reinterpret_cast<const float4*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async4(void* smem_dst, const void* gmem_src, int src_size) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    const unsigned s = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
    asm volatile("cp.async.ca.shared.global [%0], [%1], 4, %2;\n" :: "r"(s), "l"(gmem_src), "r"(src_size));
#else
    float v = 0.0f;
    if (src_size == 4) v = *reinterpret_cast<const float*>(gmem_src);
    *reinterpret_cast<float*>(smem_dst) = v;
#endif
}
__device__ __forceinline__ void cp_async_commit() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.commit_group;\n" ::);
#endif
}
template <int PENDING>
__device__ __forceinline__ void cp_async_wait() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.wait_group %0;\n" :: "n"(PENDING));
#endif
}
__global__ void __launch_bounds__(NUM_THREADS) upper_triangular_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N
) {
    // Multi-stage asynchronous pipeline (cp.async). Global->shared copies
    // are issued asynchronously and bypass the register file; STAGES-1
    // K-tiles are kept in flight so global-load latency of future tiles
    // overlaps current-tile compute, deepening the previous 2-stage
    // register-staged pipeline. A is staged row-major ([m][k]) with an
    // XOR swizzle of the float4 chunk index (physical chunk = logical
    // chunk ^ (m >> 3), row stride 32 floats) so the eight 8-row groups
    // of a warp hit distinct banks; B keeps the natural [k][n] layout.
    // Interior tiles use 16-byte cp.async; diagonal/boundary tiles use
    // 4-byte cp.async with zero-fill, preserving the exact triangular
    // masking semantics. The CTA/warp/thread tiling, the triangular
    // K-range skipping, and the output masking are unchanged.
    __shared__ __align__(16) float As[STAGES][TILE_M][SMEM_A_STRIDE];
    __shared__ __align__(16) float Bs[STAGES][TILE_K][TILE_N];
    const int tid = threadIdx.x;
    const int warp = tid >> 5;
    const int lane = tid & 31;
    const int warp_m = warp >> 1;
    const int warp_n = warp & 1;
    const int lane_m = lane >> 3;
    const int lane_n = lane & 7;
    const int frag_row = warp_m * WARP_M + lane_m * TM;
    const int frag_col = warp_n * WARP_N + lane_n * TN;
    const int row_tile = blockIdx.y;
    const int col_tile = blockIdx.x;
    const int tile_m = row_tile * TILE_M;
    const int tile_n = col_tile * TILE_N;
    const bool aligned = ((N & 3) == 0);
    // Register blocking: each thread computes a TM x TN sub-tile.
    float acc[TM][TN];
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        #pragma unroll
        for (int j = 0; j < TN; ++j) {
            acc[i][j] = 0.0f;
        }
    }
    // Product of upper triangular matrices is upper triangular.
    // For output tile (row_tile, col_tile), only k tiles in [row_tile, col_tile] contribute.
    if (row_tile <= col_tile) {
        // Cooperative copy indices (identical partition to the original).
        const int a_m0 = tid >> 2;
        const int a_m1 = a_m0 + 32;
        const int a_c = tid & 3;
        const int a_k = a_c * 4;
        const int b_k0 = tid >> 4;
        const int b_k1 = b_k0 + 8;
        const int b_n = (tid & 15) * 4;
        const int kt_begin = tile_m / TILE_K;
        int kt_end = (tile_n + TILE_N - 1) / TILE_K;
        const int kt_last = (N + TILE_K - 1) / TILE_K - 1;
        if (kt_end > kt_last) kt_end = kt_last;
        // Issue all global->shared async copies for one K-tile into a stage.
        auto issue_tile = [&](int stage, int kt) {
            const int tile_k = kt * TILE_K;
            // A: fast 16B path only when fully interior, aligned, and
            // strictly above the diagonal (the mask would be a no-op).
            const bool a_fast = aligned &&
                                (tile_m + TILE_M <= N) &&
                                (tile_k + TILE_K <= N) &&
                                (tile_k >= tile_m + TILE_M);
            if (a_fast) {
                cp_async16(&As[stage][a_m0][(a_c ^ (a_m0 >> 3)) * 4],
                           A + (size_t)(tile_m + a_m0) * N + tile_k + a_k);
                cp_async16(&As[stage][a_m1][(a_c ^ (a_m1 >> 3)) * 4],
                           A + (size_t)(tile_m + a_m1) * N + tile_k + a_k);
            } else {
                #pragma unroll
                for (int half = 0; half < 2; ++half) {
                    const int m = a_m0 + half * 32;
                    const int gr = tile_m + m;
                    #pragma unroll
                    for (int j = 0; j < 4; ++j) {
                        const int k = a_k + j;
                        const int gc = tile_k + k;
                        const bool v = (gr < N) && (gc < N) && (gr <= gc);
                        const float* src = v ? (A + (size_t)gr * N + gc) : A;
                        cp_async4(&As[stage][m][(((k >> 2) ^ (m >> 3)) * 4) + (k & 3)],
                                  src, v ? 4 : 0);
                    }
                }
            }
            // B: mask-free iff every row index <= every column index.
            const bool b_fast = aligned &&
                                (tile_k + TILE_K <= N) &&
                                (tile_n + TILE_N <= N) &&
                                (tile_k + TILE_K - 1 <= tile_n);
            if (b_fast) {
                cp_async16(&Bs[stage][b_k0][b_n],
                           B + (size_t)(tile_k + b_k0) * N + tile_n + b_n);
                cp_async16(&Bs[stage][b_k1][b_n],
                           B + (size_t)(tile_k + b_k1) * N + tile_n + b_n);
            } else {
                #pragma unroll
                for (int half = 0; half < 2; ++half) {
                    const int bk = b_k0 + half * 8;
                    const int gr = tile_k + bk;
                    #pragma unroll
                    for (int j = 0; j < 4; ++j) {
                        const int bn = b_n + j;
                        const int gc = tile_n + bn;
                        const bool v = (gr < N) && (gc < N) && (gr <= gc);
                        const float* src = v ? (B + (size_t)gr * N + gc) : B;
                        cp_async4(&Bs[stage][bk][bn], src, v ? 4 : 0);
                    }
                }
            }
        };
        // Prologue: fill the first STAGES-1 stages. One commit group per
        // stage (empty commits keep the group accounting consistent).
        #pragma unroll
        for (int s = 0; s < STAGES - 1; ++s) {
            if (kt_begin + s <= kt_end) {
                issue_tile(s, kt_begin + s);
            }
            cp_async_commit();
        }
        int cur = 0;
        for (int kt = kt_begin; kt <= kt_end; ++kt) {
            // Wait until the oldest in-flight tile (cur) has landed.
            cp_async_wait<STAGES - 2>();
            __syncthreads();
            // The barrier above guarantees every thread is done with the
            // tile consumed in the previous iteration, so its buffer can
            // be re-filled asynchronously before computing on cur.
            const int nxt = kt + (STAGES - 1);
            if (nxt <= kt_end) {
                int nbuf = cur + (STAGES - 1);
                if (nbuf >= STAGES) nbuf -= STAGES;
                issue_tile(nbuf, nxt);
            }
            cp_async_commit();
            // Compute on stage cur. Process 4 K-steps per iteration:
            // 8 float4 A fragments (rows) + 4 float4 B fragments feed
            // 128 FMAs per thread per kk4 step.
            #pragma unroll
            for (int kk4 = 0; kk4 < TILE_K / 4; ++kk4) {
                float4 bf[4];
                #pragma unroll
                for (int k = 0; k < 4; ++k) {
                    bf[k] = *reinterpret_cast<const float4*>(&Bs[cur][kk4 * 4 + k][frag_col]);
                }
                float bv[4][4];
                #pragma unroll
                for (int k = 0; k < 4; ++k) {
                    bv[k][0] = bf[k].x;
                    bv[k][1] = bf[k].y;
                    bv[k][2] = bf[k].z;
                    bv[k][3] = bf[k].w;
                }
                #pragma unroll
                for (int h = 0; h < 2; ++h) {
                    float4 af[4];
                    #pragma unroll
                    for (int i = 0; i < 4; ++i) {
                        const int m = frag_row + h * 4 + i;
                        af[i] = *reinterpret_cast<const float4*>(&As[cur][m][(kk4 ^ (m >> 3)) * 4]);
                    }
                    float av[4][4];
                    #pragma unroll
                    for (int i = 0; i < 4; ++i) {
                        av[i][0] = af[i].x;
                        av[i][1] = af[i].y;
                        av[i][2] = af[i].z;
                        av[i][3] = af[i].w;
                    }
                    #pragma unroll
                    for (int k = 0; k < 4; ++k) {
                        #pragma unroll
                        for (int i = 0; i < 4; ++i) {
                            #pragma unroll
                            for (int j = 0; j < 4; ++j) {
                                acc[h * 4 + i][j] += av[i][k] * bv[k][j];
                            }
                        }
                    }
                }
            }
            cur = (cur + 1 == STAGES) ? 0 : cur + 1;
        }
    }
    #pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int row = tile_m + frag_row + i;
        if (row < N) {
            #pragma unroll
            for (int j = 0; j < TN; ++j) {
                const int col = tile_n + frag_col + j;
                if (col < N) {
                    C[row * N + col] = (row <= col) ? acc[i][j] : 0.0f;
                }
            }
        }
    }
}
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must have the same shape");
    TORCH_CHECK(A.is_contiguous(), "A must be contiguous");
    TORCH_CHECK(B.is_contiguous(), "B must be contiguous");
    const int N = static_cast<int>(A.size(0));
    auto C = torch::empty_like(A);
    dim3 block(NUM_THREADS);
    dim3 grid((N + TILE_N - 1) / TILE_N, (N + TILE_M - 1) / TILE_M);
    auto stream = at::cuda::getCurrentCUDAStream();

    upper_triangular_matmul_kernel<<<grid, block, 0, stream>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

_ext = load_inline(
    name="upper_triangular_matmul_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["triu_matmul_cuda"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return _ext.triu_matmul_cuda(A, B)

